// Imports the isotherm results dashboard, as generated by scripts/dashboard.py in
// physicalreasoning/isotherm, into this site:
//
//   npm run import:isotherm -- path/to/generated/index.html
//
// The generated page is split into the files under src/isotherm/, which
// src/pages/isotherm/index.astro puts back together. Nothing in the page is changed.
import { readFileSync, writeFileSync } from 'node:fs';

const file = process.argv[2];
if (!file) {
  console.error('usage: npm run import:isotherm -- <generated index.html>');
  process.exit(1);
}
const html = readFileSync(file, 'utf8');

function find(re, what) {
  const m = html.match(re);
  if (!m) throw new Error(`Could not find ${what} in ${file}. Has the dashboard's page structure changed?`);
  return m;
}

const [, head] = find(/<head>\n?([\s\S]*?)<\/head>/, 'the <head>');
const [, body, code] = find(/<body>\n?([\s\S]*?)\s*<script>\n?(const D = [\s\S]*?)\n?<\/script>\s*<\/body>/,
  'the body and the dashboard script');
const [dataLine, json] = code.match(/^const D = (.*);\n/) ?? [];
if (!dataLine) throw new Error(`The dashboard script in ${file} does not start with "const D = {...};" on one line.`);

const styles = [...head.matchAll(/<style>([\s\S]*?)<\/style>/g)].map((m) => m[1].trim());
const headTags = head.replace(/\s*<style>[\s\S]*?<\/style>/g, '').trim();
const out = new URL('../src/isotherm/', import.meta.url);

writeFileSync(new URL('head.html', out), headTags + '\n');
writeFileSync(new URL('dashboard.css', out), styles.join('\n\n') + '\n');
writeFileSync(new URL('body.html', out), body.trim() + '\n');
writeFileSync(new URL('data.json', out), JSON.stringify(JSON.parse(json)) + '\n');
writeFileSync(new URL('dashboard.js', out), code.slice(dataLine.length).trim() + '\n');
console.log(`Imported ${file} into src/isotherm/.`);
